import {S,term as T,step as P,check as Q,task as A,lesson as L} from './shared.js';
export default [
L(5,1,{
 title:'SFT：让已有模型学习“怎样回答”',summary:'从两条指令与示范答案开始，解释监督微调是什么，并逐位置检查哪些内容参与损失。',prerequisites:['w3-l1','w3-l2'],
 terms:[T('后训练 post-training','在基础模型之上，为目标行为和使用方式进行的后续训练阶段。','可以包含示范学习、偏好优化等多种过程，不是单一算法。'),T('SFT，Supervised Fine-Tuning，监督微调','从已有模型出发，使用输入与期望输出的示范继续训练。','给“把这句译成英文”和一份正确译文，让模型学习这种回答行为。'),T('聊天模板 chat template','把角色、指令和回答组织成模型所需序列的具体格式。','用户和助手可能由专门的控制符区分，不能随意换成普通字符串。'),T('loss mask 损失遮挡','选择哪些输出位置参与损失的规则。','只监督回答时，指令和补齐位置可见，但不计入本次目标损失。')],
 sections:[P('第 1 步：从已经会续写的模型开始','预训练让模型学到一定的文本规律，但“会续写”不自动等于“按要求回答”。例如输入一条问题，模型可能继续写另一条问题。我们希望它输出指定形式的答案，需要提供这种行为的示范。','SFT 的三个词可以拆开理解：Supervised 表示有明确的示范目标；Fine-Tuning 表示从已有模型参数出发继续调整，而不是必然从随机权重重新开始。'),P('第 2 步：把一条示范转成完整训练序列','假设指令为“把 2+3 的结果写出来”，回答为“5”。模板把角色、指令和回答接成一个序列，模型仍逐位置预测下一 token。数据组织发生变化，底层交叉熵可以和预训练相同。','把 prompt 译为提示部分，把 response 译为回答部分。某些训练会监督完整序列，某些只监督回答。两者不能凭“SFT”这个名字确定，要查看实际标签和 loss mask。'),P('第 3 步：区分能看到与需要预测得分','如果只监督回答，指令必须保留在输入中，否则模型不知道要回答什么；只是对应位置不计入损失。因果掩码控制能看到哪些输入，loss mask 控制哪些输出参与目标，它们不是同一张表。','PyTorch 里常将不计分的标签设为 ignore_index，例如 −100。这个值是损失函数约定，不是把 −100 放进分词器词表。当回答位置全部被忽略时，这批数据可能没有有效监督。'),P('第 4 步：用几条样本验证再扩大数据','先检查模板编码后的角色、结束符和回答边界。对短示范反复训练，看模型是否能按格式输出；再用未参与训练的任务检查泛化和原能力是否下降。','小量 SFT 适合改变格式、风格和特定任务行为，不能保证凭少量示范学到大量新知识。数据正确性、覆盖范围与基础模型能力共同决定效果。')],
 worked:{title:'只监督回答时的位置账本',steps:['序列输入包含：[用户角色, 指令内容, 助手角色, 回答内容, 结束符]。','真实实现先做下一 token 对齐，再依据角色和回答边界设置有效目标。','指令仍在上下文中，但不在本例回答损失的平均分母中。','人工解码所有有效标签，确认看到的确实是回答和约定的结束标记。'],takeaway:'SFT 说明学习什么样的示范；参数更新范围要到下一课另外决定。'},
 example:{code:'tokens = ["user", "2+3=?", "assistant", "5", "EOS", "PAD"]\nis_answer = [False, False, False, True, True, False]\nselected = [t for t,keep in zip(tokens, is_answer) if keep]\nprint("supervised content", selected)\nprint("valid targets", sum(is_answer))',output:"supervised content ['5', 'EOS']\nvalid targets 2",explanation:'这只是角色边界与有效内容的示意；接入语言模型时仍需正确完成输入与标签右移，不能直接把这组字符串当作 logits。'},
 checks:[Q('SFT 为什么可能和预训练使用相同交叉熵，却学不同的行为？','比较数据组织和监督覆盖。','目标函数形式可以相同，但 SFT 的指令示范、模板、有效位置和训练目的不同。',1),Q('不监督指令，是不是应该从输入中删除指令？','模型回答需要什么条件？','不应该。指令是回答条件；不计入损失不等于从上下文移除。',2)],
 practice:{title:'先做好十条示范的体检',steps:[A('手写 10 条简单的指令与回答，包括结束条件。','每条都有明确输入、期望输出和一致格式。','不要先追求数量，先检查矛盾答案和缺失字段。'),A('画出一条样本的角色、输入、目标与 loss mask。','可以解释每个有效目标为什么被监督。','先用字符串纸面展开，再写编号代码。'),A('为数据划分保留未见过的指令形式。','评测包含新表述，避免只检查模板记忆。','训练句子的轻微复制不能充分证明泛化。')]},sources:[S.instruct,S.ce]
}),
L(5,2,{
 title:'LoRA：训练任务不变，换一种更新参数的方法',summary:'亲手计算两个小矩阵的乘积，再解释为何“用 LoRA 做 SFT”是一句完整而不矛盾的话。',prerequisites:['w5-l1','w3-l2'],
 terms:[T('全量微调','允许更新选定模型的全部基础权重。','训练自由度较大，但梯度和优化器状态的存储成本较高。'),T('LoRA，Low-Rank Adaptation，低秩适配','冻结基础矩阵 W，训练两个较小矩阵 A、B，通过 BA 为基础计算增加一项变化。','y=W*x+(alpha/r)*B*A*x；本课先令 alpha/r=1。'),T('rank r','LoRA 中间表示的宽度，限制更新矩阵能够表达的变化空间。','A 为 r×in，B 为 out×r，参数量为 r(in+out)。'),T('QLoRA','结合量化基础权重和低秩适配训练的方法。','量化改变存储数值表示；LoRA 改变训练哪些参数，两者可以组合。')],
 sections:[P('第 1 步：先知道为什么要限制更新范围','SFT 告诉我们用指令示范训练，却没规定必须更新所有权重。如果基础模型很大，全量微调会保存大量梯度和优化器状态。希望降低可训练部分的开销，就可以选参数高效的适配方式。','LoRA 是其中一种。它保留基础权重，通过额外的小矩阵学习改变量。冻结基础权重不代表删除基础模型；前向计算仍要使用它。'),P('第 2 步：把公式拆成可手算的两步','设输入 x 长度为 in，A 先把 x 映射到长度 r 的中间向量，再由 B 映射回 out 维。两步合起来就是 BAx。最后与 Wx 相加。alpha/r 是常见缩放，必须在配置里记录。','例如 in=out=2、r=1，A=[1,2]，B 的两行为 [0.1]、[0.2]。BA 的两行为 [0.1,0.2] 和 [0.2,0.4]。这是受一个中间方向约束的变化，不是随意调整四个独立数字。'),P('第 3 步：数参数，但不要混成显存比例','若 in=out=4096、r=16，基础矩阵有 16,777,216 个数；A、B 合计 131,072 个数，约为基础矩阵的 0.78125%。这里不计算偏置。','这个比例是可训练适配器参数相对基础矩阵的比例，不是总显存节省比例。基础权重、激活和临时工作区仍然存在。rank 也不是越大越好，要在能力、过拟合和资源之间实验。'),P('第 4 步：把 SFT 和 LoRA 放回各自的问题','SFT 回答“用什么示范、希望学什么行为”；LoRA 回答“通过哪些参数表达训练改动”。因此可以用 LoRA 做 SFT，也可以全量做 SFT。反过来，LoRA 也不只适用于指令示范。','常见初始化把 B 设为零、A 设为小随机值，使初始改变量为零；不能把两个矩阵都随意设成零，否则起始梯度可能卡住。推理部署时还要检查适配器是否正确加载或合并。')],
 worked:{title:'逐项构造一个秩为 1 的更新',steps:['A=[1,2]，B=[[0.1],[0.2]]。','第一行：0.1×A=[0.1,0.2]；第二行：0.2×A=[0.2,0.4]。','基础 W 为单位矩阵时，W+BA=[[1.1,0.2],[0.2,1.4]]。','这里是矩阵计算演示；真正训练需对 A、B 求梯度，并验证 W 保持冻结。'],takeaway:'学会算更新后，再讨论节省多少参数和是否适合具体任务。'},
 example:{code:'W = [[1.0, 0.0], [0.0, 1.0]]\nA, B = [[1.0, 2.0]], [[0.1], [0.2]]\nupdated = [[W[i][j] + B[i][0]*A[0][j] for j in range(2)] for i in range(2)]\nfor row in updated:\n    print(row)\nprint("adapter parameters", 16*(4096+4096))',output:'[1.1, 0.2]\n[0.2, 1.4]\nadapter parameters 131072',explanation:'这一例固定缩放为 1，并不执行训练。代码练习会进一步实现 rank 和 alpha 的处理。'},
 checks:[Q('为什么可以“用 LoRA 做 SFT”？','分别说出两个名称回答的问题。','SFT 定义示范学习任务；LoRA 定义参数更新方式，二者属于不同维度，可以同时使用。',3),Q('适配器只有基础矩阵约 0.8% 的参数，整体显存也只剩 0.8% 吗？','列出冻结后还需要保留和计算的内容。','不是。基础权重、激活等仍存在；只能据此确定这部分可训练参数量。',2)],
 practice:{title:'把更新范围查清楚',steps:[A('完成 LoRA 更新代码练习，手算秩为 1 的样例。','输出与上述矩阵相符，原 W 不被原地改坏。','核对 A、B 的乘法顺序和形状。'),A('在参数预算实验中比较 rank=4、16、64。','记录参数数量，不把它写成真实 GPU 显存。','若需要显存结论，必须在实际模型上测量。'),A('设计全量 SFT 与 LoRA SFT 的对照表。','固定基础权重、数据、评测，记录可训练范围和预算。','不同方法可能需分别调学习率，报告固定配置对照与各自调优结果的区别。')]},links:[{label:'LoRA 参数预算',href:'#/labs/lora'},{label:'LoRA 更新实现',href:'#/code/lora-update'}],sources:[S.lora,S.qlora]
}),
L(5,3,{
 title:'奖励和偏好：评价一个回答，与训练它改进',summary:'先区分打分、挑选和更新参数，再把奖励模型、DPO、PPO、GRPO 放到一张流程图上。',prerequisites:['w5-l1','w1-l2'],
 terms:[T('偏好 preference','对同一条件下多个输出的相对选择。','对问题 Q，人更喜欢回答 A 而非 B，不一定给出绝对分数。'),T('奖励 reward 与奖励模型','奖励是评价信号；奖励模型是学习输出评分的模型。','一个评分器可能认为某张图更符合提示，但其分数不是真理。'),T('RLHF','利用人类反馈构造评价信号，并据此优化模型行为的一类流程。','典型流程可能包含示范训练、偏好数据、奖励模型和策略优化。'),T('DPO','一种直接利用优选/劣选样本对调整模型相对偏好的方法。','标准形式不需要先训练独立奖励模型再做 PPO 的在线采样优化。'),T('PPO 与 GRPO','两种策略优化方法；前者常用价值估计，GRPO 常利用同组候选的相对奖励构造信号。','理解它们先要区分生成模型、评分器和参数更新步骤。')],
 sections:[P('第 1 步：打分和学习是两件事','生成 8 个回答，再用评分器挑一个最好的，这叫候选选择或重排序。只要没有根据损失更新生成模型，它的权重就没有变化。高分结果被选中，不等于模型已经学会下次更容易生成它。','把评分进一步转换成学习信号，再更新生成模型，才是奖励优化。两种流程都可能有用，但报告时要分别写清推理预算和训练改动。'),P('第 2 步：从人的选择构造偏好数据','同一问题提供 chosen 与 rejected 两个回答，表示在该标注规则下前者更受偏好。要记录标注维度，例如正确性、清晰度或风格；不同维度可能冲突。','奖励模型可从这些比较中学习排序，再给新输出打分。但它会受数据和模型限制，可能偏爱长回答或某些表面特征，因此需要独立评测。'),P('第 3 步：先认清不同优化路径','典型 PPO-RLHF 流程会让当前策略生成输出，获得奖励，估计哪些输出比预期好，再更新策略，并常使用参考策略约束改动。PPO 的裁剪目标用于限制某些过大的策略变化。','标准 DPO 使用偏好对以及参考模型的对数概率，直接优化优选相对劣选的倾向。GRPO 常对同一问题采样一组候选，通过组内相对奖励构造优势信号。本课先掌握输入数据和流程差异，不要求尚未学习强化学习细节时手写完整训练器。'),P('第 4 步：识别奖励投机和名称不确定性','如果训练奖励提高而人工盲评下降，可能是模型学会讨好评分器，这叫奖励投机或 reward hacking。应检查长度、重复、格式等是否被错误奖励，并使用未参与训练的评价。','你提过的 rewardx 还没有明确全称，不能直接断定它等于某篇论文；PT 也必须结合团队流程确认。遇到简称，记录全称、代码入口、输入输出和是否更新参数，再归类。')],
 worked:{title:'同一组三个候选，可能有两种用途',steps:['候选奖励为 [1,2,3]，均值为 2。','简单中心化信号为 [−1,0,1]，表示组内相对表现；实际 GRPO 还涉及具体归一化和优化目标。','如果只返回第 3 个候选，模型未被训练。','如果用这些评价构造目标并反向更新策略，才发生学习。'],takeaway:'先画完整流程，再判断某个 reward 名称指信号、模型还是优化方法。'},
 example:{code:'rewards = [1.0, 2.0, 3.0]\nmean_reward = sum(rewards)/len(rewards)\ncentered = [r-mean_reward for r in rewards]\nbest = max(range(len(rewards)), key=lambda i: rewards[i])\nprint("relative signals", centered)\nprint("selected candidate", best+1)',output:'relative signals [-1.0, 0.0, 1.0]\nselected candidate 3',explanation:'这里只计算组内相对信号和选择结果，没有策略概率、损失或更新，因此不是完整 GRPO 实现。'},
 checks:[Q('评分器选出了最好的一张图，能证明生成模型参数变了吗？','检查是否执行参数更新。','不能。仅排序和选择不会修改生成模型权重。',0),Q('奖励分数持续上升但独立盲评下降，该怎么解释？','评价信号与真实目标是否一致？','优先检查奖励投机、评分偏差和评测协议，不能把奖励上涨直接当作任务进步。',3)],
 practice:{title:'画出你所在团队的一条反馈流程',steps:[A('画“提示→候选→评分→选择”的链路。','能指出这条链里没有训练更新。','不要把模型调用次数增加当作训练次数增加。'),A('再补上“构造损失→反向传播→更新生成模型”的训练路径。','标出生成模型、奖励模型、参考模型的不同职责。','没有独立奖励模型的 DPO 路径应另画，不强行套同一框图。'),A('为 rewardx 和 PT 建立待查证记录。','记录原话、所在配置或页面、待确认的全称。','没找到证据时保留未知，不凭缩写填一个看似合理的答案。')]},sources:[S.instruct,S.dpo,S.grpo,S.reward]
})];
